/* داده‌های نمونه و ساختگی برای پروژه آموزشی */
IF DB_ID(N'StudentEnrollmentDB') IS NULL CREATE DATABASE StudentEnrollmentDB;
GO
USE StudentEnrollmentDB;
GO
IF OBJECT_ID(N'dbo.Enrollment',N'U') IS NOT NULL DROP TABLE dbo.Enrollment;
IF OBJECT_ID(N'dbo.Course',N'U') IS NOT NULL DROP TABLE dbo.Course;
IF OBJECT_ID(N'dbo.Student',N'U') IS NOT NULL DROP TABLE dbo.Student;
GO
CREATE TABLE dbo.Student(
 StudentID INT PRIMARY KEY,
 FullName NVARCHAR(100) NOT NULL,
 Age INT NOT NULL CHECK(Age BETWEEN 16 AND 80),
 Major NVARCHAR(100) NOT NULL,
 GPA DECIMAL(4,2) NOT NULL CHECK(GPA BETWEEN 0 AND 20),
 CompletedCredits INT NOT NULL CHECK(CompletedCredits>=0)
);
CREATE TABLE dbo.Course(
 CourseID INT PRIMARY KEY,
 CourseName NVARCHAR(100) NOT NULL,
 RelatedMajor NVARCHAR(100) NOT NULL,
 Credits INT NOT NULL CHECK(Credits BETWEEN 1 AND 6),
 Capacity INT NOT NULL CHECK(Capacity>0),
 Difficulty INT NOT NULL CHECK(Difficulty BETWEEN 1 AND 5)
);
CREATE TABLE dbo.Enrollment(
 EnrollmentID INT PRIMARY KEY,
 StudentID INT NOT NULL,
 CourseID INT NOT NULL,
 DecisionDate DATE NOT NULL,
 IsEnrolled BIT NOT NULL,
 CONSTRAINT FK_Enrollment_Student FOREIGN KEY(StudentID) REFERENCES dbo.Student(StudentID),
 CONSTRAINT FK_Enrollment_Course FOREIGN KEY(CourseID) REFERENCES dbo.Course(CourseID),
 CONSTRAINT UQ_Enrollment_Student_Course UNIQUE(StudentID,CourseID)
);
GO
GO
GO
GO

CREATE VIEW dbo.vw_Student AS SELECT StudentID,FullName,Age,Major,GPA,CompletedCredits FROM dbo.Student;
GO
CREATE VIEW dbo.vw_Course AS SELECT CourseID,CourseName,RelatedMajor,Credits,Capacity,Difficulty FROM dbo.Course;
GO
CREATE VIEW dbo.vw_Enrollment AS SELECT EnrollmentID,StudentID,CourseID,DecisionDate,IsEnrolled FROM dbo.Enrollment;
GO
SELECT COUNT(*) AS StudentCount FROM dbo.vw_Student;
SELECT COUNT(*) AS CourseCount FROM dbo.vw_Course;
SELECT COUNT(*) AS EnrollmentCount FROM dbo.vw_Enrollment;
GO
